func parseResponse(resp *resty.Response) (*AuthSuccess, error) {
	// 1. 获取 []byte 类型的响应体
	byt := resp.Body()

	// 2. 声明目标结构体指针
	var result AuthSuccess

	// 3. 将 []byte 反序列化到结构体中
	err := json.Unmarshal(byt, &result)
	if err != nil {
		return nil, err
	}

	return &result, nil
}